/*-- Button Go Top --*/
body.tpl-rosaline .ro-shell #goTop {
  position: fixed;
  padding: 0;
  bottom: 40px;
  right: 20px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--white);
  color: var(--white);
  cursor: pointer;
  border: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08), 0 12px 30px rgba(0, 0, 0, 0.12);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  -webkit-transition: all 0.3s ease;
  -moz-transition: all 0.3s ease;
  -ms-transition: all 0.3s ease;
  -o-transition: all 0.3s ease;
  transition: all 0.3s ease;
}
body.tpl-rosaline .ro-shell #goTop.pst-2 {
  bottom: 160px;
}
body.tpl-rosaline .ro-shell #goTop .border-progress {
  position: absolute;
  top: -1px;
  left: -1px;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  border: 1px solid var(--black);
  mask-image: conic-gradient(var(--black) var(--progress-angle, 0deg), transparent 0);
  -webkit-mask-image: conic-gradient(var(--black) var(--progress-angle, 0deg), transparent 0);
  content: "";
  z-index: 1;
  -webkit-transition: all 0.3s ease;
  -moz-transition: all 0.3s ease;
  -ms-transition: all 0.3s ease;
  -o-transition: all 0.3s ease;
  transition: all 0.3s ease;
  border-radius: 50%;
}
body.tpl-rosaline .ro-shell #goTop.show {
  opacity: 1;
  visibility: visible;
}
body.tpl-rosaline .ro-shell #goTop .icon {
  color: var(--black);
}
body.tpl-rosaline .ro-shell #goTop .ic-wrap {
  -webkit-transition: all 0.3s ease;
  -moz-transition: all 0.3s ease;
  -ms-transition: all 0.3s ease;
  -o-transition: all 0.3s ease;
  transition: all 0.3s ease;
  animation: rosaline-reference-iconBounce 2s linear 0s infinite;
  display: flex;
}
body.tpl-rosaline .ro-shell #goTop:hover {
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}
